fn is_digit(c: Str) -> Bool {
  return c == "0" or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn is_lower(c: Str) -> Bool {
  let k = c.codes().get_or(0, 0)
  return k >= 97 and k <= 122
}

fn is_name(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  return t.chars().all(fn(c) => is_lower(c))
}

fn is_number(t: Str) -> Bool {
  var body = t
  if t.starts_with("-") {
    body = t.slice(1, t.len())
  }
  if body.is_empty() {
    return false
  }
  return body.chars().all(fn(c) => is_digit(c))
}

fn is_term(t: Str) -> Bool {
  return is_number(t) or is_name(t)
}

fn line_ok(parts: List[Str]) -> Bool {
  let n = parts.len()
  if n < 3 or n % 2 == 0 {
    return false
  }
  if parts.get_or(1, "") != "=" or (not (is_name(parts.get_or(0, "")))) {
    return false
  }
  for k in range(2, n) {
    let t = parts.get_or(k, "")
    if k % 2 == 0 {
      if not (is_term(t)) {
        return false
      }
    } else {
      if t != "+" and t != "-" {
        return false
      }
    }
  }
  return true
}

fn term_value(t: Str, vars: Map[Str, Int]) -> Result[Int, Str] {
  if is_number(t) {
    if t.starts_with("-") {
      return Ok(0 - t.slice(1, t.len()).to_int().unwrap_or(0))
    }
    return Ok(t.to_int().unwrap_or(0))
  }
  return match vars.get(t) {
    Some(v) => Ok(v),
    None => Err("undefined {t}"),
  }
}

fn eval_line(parts: List[Str], vars: Map[Str, Int]) -> Result[Int, Str] {
  var acc = term_value(parts.get_or(2, ""), vars)?
  for k in range(3, parts.len()) {
    if k % 2 == 1 {
      let v = term_value(parts.get_or(k + 1, ""), vars)?
      if parts.get_or(k, "") == "+" {
        acc = acc + v
      } else {
        acc = acc - v
      }
    }
  }
  return Ok(acc)
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  var vars: Map[Str, Int] = Map {}
  for line in lines {
    let parts = line.split(" ")
    if not (line_ok(parts)) {
      return Err("syntax error")
    }
    let v = eval_line(parts, vars)?
    vars = vars.set(parts.get_or(0, ""), v)
  }
  return Ok(vars)
}
